<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Attendance and Leave Summary</title><link rel="stylesheet" href="../public/css/style.css"><link rel="stylesheet" href="../public/css/dashboard.css?v=20260909-2"><link rel="stylesheet" href="../public/css/employee-documents-fixes.css?v=20260921-5"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><style><?php $template=file_get_contents(__DIR__.'/employee_documents_expiring.php');if(preg_match('/<style>(.*?)<\/style>/s',$template,$match))echo $match[1];?>.year-form{display:flex;align-items:center;gap:8px}.year-form input,.leave-table input{padding:8px;border:1px solid #cbdce5;border-radius:7px}.year-form input{width:90px}.leave-table input{width:82px}.leave-table td,.leave-table th{text-align:center}.leave-table td:nth-child(-n+3),.leave-table th:nth-child(-n+3){text-align:left}.save-cell{min-width:95px}@media(max-width:700px){.page-head{flex-direction:column}.year-form{width:100%}}</style><link rel="stylesheet" href="../public/css/module-theme.css?v=18">
<script defer src="../public/js/nursync-ui.js?v=4"></script></head><body class="module-ui"><?php include '../includes/employee_documents_sidebar.php';?><main class="ed-expiring-main"><header class="page-head"><div><h1><i class="fa-solid fa-calendar-check"></i> Attendance &amp; Leave Summary</h1><p>Yearly employee totals for lateness and used leave credits.</p></div><form class="year-form" method="get"><input type="hidden" name="view" value="attendance_leave"><label>Year <input type="number" name="year" min="2000" max="2100" value="<?=$leaveYear?>"></label><button class="btn" type="submit">View</button></form></header><?php if($error):?><div class="alert alert-danger"><?=h($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=h($success)?></div><?php endif;?><section class="panel"><div class="table-wrap"><table class="table leave-table"><thead><tr><th>Employee ID</th><th>Employee</th><th>Department</th><th>Late Count</th><th>VL Used</th><th>SL Used</th><th>SPL Used</th><th>Wellness Used</th><th>Calamity Used</th><?php if($canMarkResigned):?><th>Action</th><?php endif;?></tr></thead><tbody><?php foreach($employees as$employee):$summary=$leaveSummaries[(int)$employee['user_id']]??[];?><tr><form method="post"><?=csrfField()?><input type="hidden" name="action" value="save_leave_summary"><input type="hidden" name="return_view" value="attendance_leave"><input type="hidden" name="employee_id" value="<?=$employee['user_id']?>"><input type="hidden" name="record_year" value="<?=$leaveYear?>"><td><?=h($employee['employee_id']?:$employee['user_id'])?></td><td><strong><?=h($employee['name'])?></strong><br><small><?=h($employee['position']?:str_replace('_',' ',$employee['role']))?></small></td><td><?=h(str_replace('_',' ',$employee['department']??''))?></td><td><input type="number" min="0" name="late_count" value="<?=(int)($summary['late_count']??0)?>" <?=$canMarkResigned?'':'readonly'?>></td><td><input type="number" min="0" step="0.5" name="vacation_leave_used" value="<?=h($summary['vacation_leave_used']??'0')?>" <?=$canMarkResigned?'':'readonly'?>></td><td><input type="number" min="0" step="0.5" name="sick_leave_used" value="<?=h($summary['sick_leave_used']??'0')?>" <?=$canMarkResigned?'':'readonly'?>></td><td><input type="number" min="0" step="0.5" name="special_privilege_leave_used" value="<?=h($summary['special_privilege_leave_used']??'0')?>" <?=$canMarkResigned?'':'readonly'?>></td><td><input type="number" min="0" step="0.5" name="wellness_leave_used" value="<?=h($summary['wellness_leave_used']??'0')?>" <?=$canMarkResigned?'':'readonly'?>></td><td><input type="number" min="0" step="0.5" name="calamity_leave_used" value="<?=h($summary['calamity_leave_used']??'0')?>" <?=$canMarkResigned?'':'readonly'?>></td><?php if($canMarkResigned):?><td class="save-cell"><button class="btn" type="submit">Save</button></td><?php endif;?></form></tr><?php endforeach;?><?php if(!$employees):?><tr><td colspan="10" class="empty">No active employees found.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
